"""Fill remaining Cinema Rack axes. Not imported by pytest."""

from __future__ import annotations

import json
from pathlib import Path

OUT = Path(__file__).resolve().parents[2] / "custom_nodes" / "ez_prompt_enhance" / "cinema"


def e(
    tid: str,
    label: str,
    clause: str,
    *,
    still: str = "",
    wan: str = "",
    audio: str = "",
    still_ok: bool = True,
    motion_ok: bool = True,
    av_ok: bool = True,
    conflicts: tuple[str, ...] = (),
    tags: tuple[str, ...] = (),
) -> dict:
    if not clause.endswith("."):
        clause += "."
    if still and not still.endswith("."):
        still += "."
    return {
        "id": tid,
        "label": label,
        "clause": clause,
        "still": still,
        "wan_token": wan,
        "audio": audio,
        "still_ok": still_ok,
        "motion_ok": motion_ok,
        "av_ok": av_ok,
        "conflicts": list(conflicts),
        "tags": list(tags),
    }


def dump(name: str, rows: list[dict]) -> None:
    path = OUT / name
    path.write_text(json.dumps(rows, indent=2) + "\n", encoding="utf-8")
    print(name, len(rows))


