def main() -> None:
    dump("composition.json", composition())
    dump("lenses_optics.json", lenses())
    dump("color_film_look.json", color())
    for name, fn in (
        ("composition.json", composition),
        ("lenses_optics.json", lenses),
        ("color_film_look.json", color),
    ):
        n = len(fn())
        if n < 100:
            raise SystemExit(f"{name} {n}")


if __name__ == "__main__":
    main()
